    'The e-mail login code of OPNV-WP is already on in this site. Use one of them, not both.' => 'اس سائٹ پر OPNV-WP کا ای میل لاگ ان کوڈ پہلے سے چالو ہے۔ دونوں میں سے ایک استعمال کریں، دونوں نہیں۔',
    'Without SMTP the code may not arrive and you would be locked out. Set up Site mail (SMTP) first.' => 'SMTP کے بغیر کوڈ شاید نہ پہنچے اور آپ باہر بند ہو جائیں گے۔ پہلے سائٹ میل (SMTP) ترتیب دیں۔',
    'Too many attempts. Try again later.' => 'بہت زیادہ کوششیں۔ بعد میں دوبارہ کوشش کریں۔',
    'This account needs a code sent by e-mail. Log in from %s to receive it.' => 'اس اکاؤنٹ کو ای میل سے بھیجا گیا کوڈ چاہیے۔ کوڈ حاصل کرنے کے لیے %s سے لاگ ان کریں۔',
    'The login code could not be sent by e-mail. If you own this site and are locked out, add define(\'DRACO_MFA_OFF\', true); to wp-config.php.' => 'لاگ ان کوڈ ای میل سے نہیں بھیجا جا سکا۔ اگر آپ اس سائٹ کے مالک ہیں اور باہر بند ہیں تو wp-config.php میں define(\'DRACO_MFA_OFF\', true); شامل کریں۔',
    'Hello %s,' => 'سلام %s،',
    '[%s] Confirm your recovery e-mail' => '[%s] اپنی بازیابی ای میل کی تصدیق کریں',
    'Confirm your recovery e-mail' => 'اپنی بازیابی ای میل کی تصدیق کریں',
    'Type this code in the recovery e-mail screen to confirm the change:' => 'تبدیلی کی تصدیق کے لیے یہ کوڈ بازیابی ای میل والی اسکرین میں لکھیں:',
    'It expires in 15 minutes. If you did not ask for this, someone has access to your account: change your password.' => 'اس کی میعاد 15 منٹ ہے۔ اگر آپ نے یہ نہیں مانگا تو کسی کو آپ کے اکاؤنٹ تک رسائی ہے: اپنا پاس ورڈ بدلیں۔',
    '[%s] Your login code' => '[%s] آپ کا لاگ ان کوڈ',
    'Your login code' => 'آپ کا لاگ ان کوڈ',
    'Use this code to finish logging in:' => 'لاگ ان مکمل کرنے کے لیے یہ کوڈ استعمال کریں:',
    'It expires in %d minutes. If you did not try to log in, someone knows your password: change it.' => 'اس کی میعاد %d منٹ ہے۔ اگر آپ نے لاگ ان کی کوشش نہیں کی تو کوئی آپ کا پاس ورڈ جانتا ہے: اسے بدلیں۔',
    'The code has expired. Log in again.' => 'کوڈ کی میعاد ختم ہو گئی۔ دوبارہ لاگ ان کریں۔',
    'The recovery e-mail cannot be used right now. Try again later.' => 'بازیابی ای میل ابھی استعمال نہیں ہو سکتی۔ بعد میں دوبارہ کوشش کریں۔',
    'A new code is on its way. Check your spam folder too.' => 'نیا کوڈ آ رہا ہے۔ اسپام فولڈر بھی دیکھیں۔',
    'The code could not be sent again.' => 'کوڈ دوبارہ نہیں بھیجا جا سکا۔',
    'Too many attempts. Log in again.' => 'بہت زیادہ کوششیں۔ دوبارہ لاگ ان کریں۔',
    'Wrong code.' => 'غلط کوڈ۔',
    'We have sent a 6-digit code to %s. Check your spam folder too.' => 'ہم نے %s پر 6 ہندسوں کا کوڈ بھیجا ہے۔ اسپام فولڈر بھی دیکھیں۔',
    'Login code' => 'لاگ ان کوڈ',
    'Code' => 'کوڈ',
    'Trust this device for %d days' => 'اس آلے پر %d دن بھروسہ کریں',
    'Remember me' => 'مجھے یاد رکھیں',
    'Verify and log in' => 'تصدیق کر کے لاگ ان کریں',
    'Send the code again' => 'کوڈ دوبارہ بھیجیں',
    'I cannot reach this mailbox: use my recovery e-mail' => 'میں اس میل باکس تک نہیں پہنچ سکتا: میری بازیابی ای میل استعمال کریں',
    '← Back to log in' => '← لاگ ان پر واپس',
    'Access restricted' => 'رسائی محدود',
    'Recovery e-mail' => 'بازیابی ای میل',
    'Your recovery e-mail has been changed.' => 'آپ کی بازیابی ای میل بدل دی گئی ہے۔',
    'This address is no longer your recovery e-mail.' => 'یہ پتا اب آپ کی بازیابی ای میل نہیں ہے۔',
    'Your password has been reset. The next login code will be sent to this address.' => 'آپ کا پاس ورڈ ری سیٹ ہو گیا۔ اگلا لاگ ان کوڈ اسی پتے پر بھیجا جائے گا۔',
    'The main e-mail of your account has been changed.' => 'آپ کے اکاؤنٹ کی بنیادی ای میل بدل دی گئی ہے۔',
    'If this was not you, log in with your recovery e-mail and change your password.' => 'اگر یہ آپ نہیں تھے تو اپنی بازیابی ای میل سے لاگ ان کریں اور پاس ورڈ بدلیں۔',
    'Security notice' => 'حفاظتی اطلاع',
    'We have sent a code to the new address. Type it below.' => 'ہم نے نئے پتے پر کوڈ بھیجا ہے۔ نیچے لکھیں۔',
